def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Aggregate counts
    my_c = 0
    my_d = 0
    op_c = 0
    op_d = 0
    for me, op in history:
        if me == 'C':
            my_c += 1
        else:
            my_d += 1
        if op == 'C':
            op_c += 1
        else:
            op_d += 1

    opp_rate = op_c / n
    my_rate = my_c / n

    # Recent window
    w = 12
    recent = history[-w:] if n >= w else history
    rn = len(recent)
    rop_c = 0
    for _, op in recent:
        if op == 'C':
            rop_c += 1
    rop_rate = rop_c / rn

    last_me, last_op = history[-1]

    # Endgame exploitation: if opponent cooperates a lot, take advantage late.
    if n >= 90:
        if opp_rate >= 0.7:
            return 'D'
        if opp_rate <= 0.3:
            return 'D'
        # mixed: defect to grab points
        return 'D'

    # Detect unconditional defector quickly
    if op_c == 0 and n >= 2:
        return 'D'

    # Detect nearly-pure cooperator: cooperate mostly, occasional take
    if op_d == 0 and n >= 4:
        if n % 7 == 6:
            return 'D'
        return 'C'

    # If opponent recently very cooperative, cooperate but occasionally exploit
    if rop_rate >= 0.85 and rn >= 6:
        if rng.random() < 0.08:
            return 'D'
        return 'C'

    # If opponent recently very defective, defect
    if rop_rate <= 0.25 and rn >= 4:
        # but occasionally probe cooperation to escape DD lock
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # Mutual defection streak: try to restart cooperation
    if n >= 4:
        streak_dd = 0
        for me, op in reversed(history):
            if me == 'D' and op == 'D':
                streak_dd += 1
            else:
                break
        if streak_dd >= 3:
            return 'C'

    # Opponent last defected
    if last_op == 'D':
        if last_me == 'C':
            # One-shot retaliation with a small forgiveness chance
            if opp_rate >= 0.6 and rng.random() < 0.25:
                return 'C'
            return 'D'
        else:
            # We both defected; try to break cycle based on their overall rate
            if opp_rate >= 0.5:
                if rng.random() < 0.4:
                    return 'C'
                return 'D'
            else:
                if rng.random() < 0.15:
                    return 'C'
                return 'D'

    # Opponent last cooperated
    if last_me == 'D':
        # Return to cooperation if they're not too defective
        if opp_rate >= 0.4:
            return 'C'
        # Against low-cooperator, maybe keep punishing slightly
        if rng.random() < 0.5:
            return 'C'
        return 'D'

    # Both cooperated last round
    if opp_rate >= 0.55:
        # Slight opportunism against very cooperative opponents
        if opp_rate >= 0.85 and n >= 10 and rng.random() < 0.07:
            return 'D'
        return 'C'

    # Moderate opponent: cooperate when recent is decent, else defect
    if rop_rate >= 0.5:
        return 'C'
    if rop_rate >= 0.35:
        if rng.random() < 0.65:
            return 'C'
        return 'D'
    return 'D'
